<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {queryField} from './query-state'
import {Search,Plus,MessageSquareText,Archive,RotateCcw,Trash2,Pencil,Download} from 'lucide-vue-next'
import {api,ApiError} from '../api'
import {useRequestScope} from '../platform/request-scope'
import Sheet from '../components/Sheet.vue'
import PageHeader from './PageHeader.vue'
import {promptApi,type AuthorPrompt} from './prompt-api'
const capture=useRequestScope(),items=ref<AuthorPrompt[]>([]),search=queryField('q'),archiveQuery=queryField('archived'),archived=computed({get:()=>archiveQuery.value==='1',set:(v:boolean)=>archiveQuery.value=v?'1':''}),loading=ref(true),error=ref(''),notice=ref(''),busy=ref(false),editing=ref(false),selected=ref<AuthorPrompt>(),title=ref(''),description=ref(''),content=ref(''),language=ref('zh-CN'),confirmDelete=ref<AuthorPrompt>(),conflict=ref(false)
let epoch=0,editEpoch=0,creationKey=''
const languages:Record<string,string>={'zh-CN':'简体中文','zh-TW':'繁体中文',en:'English',ja:'日本語',ko:'한국어'}
const visible=computed(()=>items.value.filter(p=>(archived.value?p.status==='archived':p.status==='active')&&(p.title+p.description+p.content).toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase())))
async function load(){const scope=capture(),version=++epoch;loading.value=true;error.value='';try{const result=await promptApi.list();if(scope.valid()&&version===epoch)items.value=result.items}catch(e){if(scope.valid()&&version===epoch)error.value=(e as Error).message}finally{if(scope.valid()&&version===epoch)loading.value=false}}
function edit(p?:AuthorPrompt){editEpoch++;selected.value=p;title.value=p?.title||'';description.value=p?.description||'';content.value=p?.content||'';language.value=p?.language||'zh-CN';creationKey=crypto.randomUUID();error.value='';conflict.value=false;editing.value=true}
function close(){if(busy.value)return;editEpoch++;editing.value=false;selected.value=undefined;content.value='';error.value=''}
async function save(){if(busy.value)return;const scope=capture(),version=editEpoch,target=selected.value;busy.value=true;error.value='';try{await api('/product/prompts'+(target?'/'+target.id:''),{method:target?'PUT':'POST',body:{title:title.value,description:description.value,language:language.value,content:content.value,expectedVersion:target?.version||0,requestKey:creationKey}});if(scope.valid()&&version===editEpoch){editing.value=false;notice.value='私人提示词已保存，可以在世界中启用。';await load()}}catch(e){if(scope.valid()&&version===editEpoch){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&e.code==='VERSION_CONFLICT'}}finally{if(scope.valid()&&version===editEpoch)busy.value=false}}
async function setStatus(p:AuthorPrompt){if(busy.value)return;const scope=capture();busy.value=true;error.value='';try{await api('/product/prompts/'+p.id,{method:'PATCH',body:{expectedVersion:p.version,status:p.status==='active'?'archived':'active'}});if(scope.valid()){notice.value=p.status==='active'?'已移入回收站；下一轮不会继续使用。':'已恢复；世界中保存的启用列表会再次生效。';await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function destroy(){const p=confirmDelete.value;if(!p||busy.value)return;const scope=capture();busy.value=true;error.value='';try{await api('/product/prompts/'+p.id+'?expectedVersion='+p.version,{method:'DELETE'});if(scope.valid()){confirmDelete.value=undefined;notice.value='提示词已彻底删除；历史任务中的使用版本仍保留。';await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
function download(p:AuthorPrompt){const url=URL.createObjectURL(new Blob([JSON.stringify({title:p.title,description:p.description,language:p.language,content:p.content},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=p.title.replace(/[<>:"/\\|?*]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>40000)throw new Error('文件过大，请选择 40 KB 以内的 JSON。');const value=JSON.parse(await file.text());if(typeof value.title!=='string'||typeof value.content!=='string'||!value.content.trim()||value.content.length>6000)throw new Error('请选择含名称与正文的提示词 JSON。');edit();title.value=value.title.slice(0,100);description.value=typeof value.description==='string'?value.description.slice(0,500):'';content.value=value.content;language.value=value.language in languages?value.language:'zh-CN'}catch(e){error.value=(e as Error).message}finally{(event.target as HTMLInputElement).value=''}}
onMounted(load)
</script>
<template><div class="workspace-page"><PageHeader title="我的提示词" eyebrow="提示词管理" description="保存自己的写作偏好，在互动世界中按需启用。"><label class="workspace-search"><Search :size="18"/><input v-model="search" type="search" aria-label="搜索提示词" placeholder="搜索提示词"></label><button class="primary" @click="edit()"><Plus :size="18"/>新增提示词</button></PageHeader><div class="workspace-collection-filters"><nav class="workspace-pills" aria-label="提示词分类"><button :aria-pressed="!archived" @click="archived=false">全部</button><button :aria-pressed="archived" @click="archived=true"><Archive :size="16"/>回收站</button></nav><label class="workspace-file-button">导入 JSON<input type="file" accept=".json,application/json" aria-label="导入提示词 JSON" @change="importFile"></label></div><p v-if="error&&!editing&&!confirmDelete" class="error" role="alert">{{error}} <button @click="load">重新加载</button></p><p v-if="notice" class="product-hint" role="status">{{notice}}</p><p v-if="loading" role="status" class="workspace-loading">正在加载提示词…</p><section v-else-if="!visible.length" class="workspace-empty"><MessageSquareText :size="42"/><h2>{{search?'没有找到提示词':archived?'回收站是空的':'目前没有提示词'}}</h2><p>{{archived?'归档的提示词会出现在这里，可以恢复或彻底删除。':'新增提示词后会出现在这里；自己的草稿可以直接用于游玩。'}}</p><button v-if="!search&&!archived" @click="edit()">新增第一条提示词</button><button v-if="search" @click="search=''">清除搜索</button></section><div v-else class="workspace-feature-grid"><article v-for="p in visible" :key="p.id" class="workspace-card prompt-card"><div class="row between"><span class="capability-badge" :data-status="p.status==='active'?'ready':'planned'">{{p.status==='active'?'私人草稿':'已归档'}}</span><small>{{languages[p.language]}}</small></div><h2>{{p.title}}</h2><p>{{p.description||'还没有简介'}}</p><small>{{p.characters.toLocaleString()}} 字符 · 版本 {{p.version}}</small><div class="workspace-card-actions"><button :disabled="busy" @click="edit(p)"><Pencil :size="15"/>编辑</button><button :disabled="busy" @click="setStatus(p)"><Archive v-if="p.status==='active'" :size="15"/><RotateCcw v-else :size="15"/>{{p.status==='active'?'归档':'恢复'}}</button><button aria-label="导出提示词" @click="download(p)"><Download :size="15"/></button><button v-if="archived" class="danger" :disabled="busy" @click="confirmDelete=p"><Trash2 :size="15"/>彻底删除</button></div></article></div><p class="workspace-footnote">仅当前账号可见，所有语言的草稿都会显示。公开提示词库与发布审核暂未开放。字数不等于模型实际 token 消耗。</p><Sheet v-if="editing" :title="selected?'编辑提示词':'新增提示词'" @close="close"><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="conflict" class="hint">你的输入仍在。关闭编辑器并重新加载，可查看最新版本。</p><form @submit.prevent="save"><label>语言<select v-model="language" aria-label="语言" :disabled="busy"><option v-for="(label,code) in languages" :key="code" :value="code">{{label}}</option></select></label><label>名称<input v-model="title" required maxlength="100" :disabled="busy" placeholder="例如：克制、细腻的悬疑叙事"></label><label>简介<textarea v-model="description" maxlength="500" rows="2" :disabled="busy"></textarea></label><label>提示词正文<textarea v-model="content" required maxlength="6000" rows="10" :disabled="busy" placeholder="描述你希望的写作风格、节奏或表达方式"></textarea></label><p class="product-note">{{content.length.toLocaleString()}} / 6,000 字符。仅用于叙事风格，物品、任务与结局仍遵循世界确认的状态。</p><div class="actions"><button type="button" :disabled="busy" @click="close">取消</button><button class="primary" :disabled="busy||conflict||!title.trim()||!content.trim()">{{busy?'正在保存…':'保存私人草稿'}}</button></div></form></Sheet><Sheet v-if="confirmDelete" title="彻底删除提示词" @close="!busy&&(confirmDelete=undefined)"><p>删除「{{confirmDelete.title}}」？这项操作不能撤销，已排队与历史任务仍保留当时使用的版本。</p><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button :disabled="busy" @click="confirmDelete=undefined">保留</button><button class="danger" :disabled="busy" @click="destroy">确认彻底删除</button></div></Sheet></div></template>
